/*
 * V8 Event
 * TableKey: sys_menu
 * EventType: InFormV8
 * Version: v1.0.1
 * Function:
 * - 模块引擎表单进入时根据 OpenType 控制微服务相关字段显隐，并按所选微服务加载页面/路由列表；选择微服务联动支持 V8.ThisValue、服务 Id、显示文本和 MicroServiceKey 兜底。
 */

if (V8.FormMode == 'Add') {
  V8.FormSet('Display', true);
}

window.GetOpenTypeKey = function (form) {
  var openType = form ? form.OpenType : '';
  if (!openType) return '';
  if (typeof openType == 'string') return openType;
  return openType.Key || openType.Value || openType.Name || '';
}

window.GetMicroServiceSelectId = function (value) {
  if (!value) return '';
  if (typeof value == 'string') {
    if (value.indexOf('（') > -1 || value.indexOf('(') > -1) return '';
    return value;
  }
  return value.Id || value.id || value.Value || value.value || value.MicroServiceId || value.MsId || '';
}

window.GetMicroServiceSelectKey = function (value) {
  if (!value) return '';
  if (typeof value == 'string') {
    var cnMatch = value.match(/（([^）]+)）/);
    if (cnMatch && cnMatch[1]) return cnMatch[1];
    var enMatch = value.match(/\(([^)]+)\)/);
    if (enMatch && enMatch[1]) return enMatch[1];
    return '';
  }
  if (value.MsKey || value.msKey || value.AppKey || value.appKey) {
    return value.MsKey || value.msKey || value.AppKey || value.appKey;
  }
  return window.GetMicroServiceSelectKey(value.Name || value.name || value.Label || value.label || '');
}

window.ApplyMicroServicePage = function (v8, page) {
  page = page || {};
  if (page.MenuUrl) v8.FormSet('Url', page.MenuUrl);
  if (page.RoutePath) v8.FormSet('MicroServiceRoutePath', page.RoutePath);
  v8.FormSet('ComponentName', 'MicroAppHost');
  v8.FormSet('ComponentPath', '/micro-app/host');
  v8.FormSet('DiyTableId', '');
  v8.FormSet('IsMicroiService', 0);
}

window.LoadMicroServicePages = function (v8, keepValue, selectedValue) {
  var selected = selectedValue || v8.Form.MicroServiceId;
  var microServiceId = window.GetMicroServiceSelectId(selected);
  var microServiceKey = window.GetMicroServiceSelectKey(selected);
  if (!microServiceId && !microServiceKey) {
    v8.FieldSet('MicroServicePageId', 'Data', []);
    if (!keepValue) {
      v8.FormSet('MicroServicePageId', '');
      v8.FormSet('MicroServiceRoutePath', '');
      v8.FormSet('Url', '');
    }
    return;
  }

  var applyRows = function (result) {
    var rows = result && result.Code == 1 && result.Data ? result.Data : [];
    for (var i = 0; i < rows.length; i++) {
      rows[i].Name = (rows[i].PageTitle || rows[i].RoutePath || rows[i].Id) + '（' + (rows[i].RoutePath || '/') + '）';
    }
    v8.FieldSet('MicroServicePageId', 'Data', rows);
    if (!keepValue) {
      v8.FormSet('MicroServicePageId', '');
      v8.FormSet('MicroServiceRoutePath', '');
      v8.FormSet('Url', '');
    }
  };

  var queryPages = function (where) {
    V8.FormEngine.GetTableData('sys_microiservice_page', {
      _Where: where,
      _SelectFields: ['Id', 'PageTitle', 'RoutePath', 'MenuUrl', 'Sort'],
      _OrderBy: 'Sort',
      _OrderByType: 'ASC',
      _PageSize: 200
    }, applyRows);
  };

  if (microServiceId) {
    V8.FormEngine.GetTableData('sys_microiservice_page', {
      _Where: [
        ['MicroServiceId', '=', microServiceId]
      ],
      _SelectFields: ['Id', 'PageTitle', 'RoutePath', 'MenuUrl', 'Sort'],
      _OrderBy: 'Sort',
      _OrderByType: 'ASC',
      _PageSize: 200
    }, function (result) {
      var rows = result && result.Code == 1 && result.Data ? result.Data : [];
      if (rows.length || !microServiceKey) {
        applyRows(result);
      } else {
        queryPages([['MicroServiceKey', '=', microServiceKey]]);
      }
    });
  } else {
    queryPages([['MicroServiceKey', '=', microServiceKey]]);
  }
}

window.OpenTypeChange = function (v8) {
  var openTypeKey = window.GetOpenTypeKey(v8.Form);
  var isMicroService = openTypeKey == 'MicroService';

  v8.FieldSet('DiyTableId', 'Visible', openTypeKey == 'Diy');
  v8.FieldSet('ComponentName', 'Visible', openTypeKey == 'Diy' || openTypeKey == 'Report');
  v8.FieldSet('MicroServiceId', 'Visible', isMicroService);
  v8.FieldSet('MicroServicePageId', 'Visible', isMicroService);
  v8.FieldSet('MicroServiceRoutePath', 'Visible', isMicroService);

  if (openTypeKey == 'Diy') {
    v8.FieldSet('ComponentPath', 'Visible', true);
    v8.FieldSet('ReportName', 'Visible', false);
  } else if (openTypeKey == 'Component') {
    v8.FieldSet('ComponentPath', 'Visible', true);
    v8.FieldSet('ReportName', 'Visible', false);
  } else if (openTypeKey == 'Report') {
    v8.FieldSet('ComponentPath', 'Visible', true);
    v8.FieldSet('ReportName', 'Visible', true);
  } else if (openTypeKey == 'Iframe' || openTypeKey == 'SecondMenu') {
    v8.FieldSet('ComponentPath', 'Visible', false);
    v8.FieldSet('ReportName', 'Visible', false);
  } else if (openTypeKey == 'PageEngine') {
    v8.FieldSet('ComponentPath', 'Visible', true);
    v8.FieldSet('ReportName', 'Visible', false);
    v8.FormSet('ComponentPath', '/page-engine/renderer');
  } else if (isMicroService) {
    v8.FieldSet('DiyTableId', 'Visible', false);
    v8.FieldSet('ComponentName', 'Visible', false);
    v8.FieldSet('ComponentPath', 'Visible', false);
    v8.FieldSet('ReportName', 'Visible', false);
    // v8.FieldSet('Url', 'Visible', false);
    v8.FormSet('ComponentName', 'MicroAppHost');
    v8.FormSet('ComponentPath', '/micro-app/host');
    v8.FormSet('DiyTableId', '');
    v8.FormSet('IsMicroiService', 0);
    window.LoadMicroServicePages(v8, true);
  } else {
    v8.FieldSet('ComponentPath', 'Visible', false);
    v8.FieldSet('ReportName', 'Visible', false);
  }

  if (!isMicroService) {
    // v8.FieldSet('Url', 'Visible', openTypeKey == 'Iframe' || openTypeKey == 'Url');
  }
  v8.FieldSet('SecondMenuWidth', 'Visible', openTypeKey == 'SecondMenu');
  v8.FieldSet('SecondMenuHeight', 'Visible', openTypeKey == 'SecondMenu');
  v8.FieldSet('SecondMenuLineCount', 'Visible', openTypeKey == 'SecondMenu');
  v8.FieldSet('SecondMenuColumn', 'Visible', openTypeKey == 'SecondMenu');
  v8.FieldSet('SecondMenuRow', 'Visible', openTypeKey == 'SecondMenu');
  v8.FieldSet('FlowDesignId', 'Visible', openTypeKey == 'WorkFlow');
}

